export function getMNMLAProfile(acNo: number): MLAProfile | undefined {
  return MN_MLA_PROFILES.find(p => p.acNo === acNo);
}

export function getMNMLAsByParty(party: string): MLAProfile[] {
  return MN_MLA_PROFILES.filter(p => p.party === party);
}

export function getMNFemaleMLAs(): MLAProfile[] {
  return MN_MLA_PROFILES.filter(p => p.gender === 'F');
}
